        self.holidays.add(day)

    def request(self, employee: str, start: date, end: date, today: date) -> int:
        """Request leave from start to end (inclusive); returns the number of leave days used."""
        if end < start:
            raise ValueError("End date cannot be before start date.")

        if (start - today).days < 3:
            raise ValueError("Leave request must be made at least 3 days before start date.")

        # Count requested leave days per calendar year
        days_by_year: dict[int, int] = defaultdict(int)
        current = start
        while current <= end:
            # Weekdays are 0-4 (Monday to Friday)
            if current.weekday() < 5 and current not in self.holidays:
                days_by_year[current.year] += 1
            current += timedelta(days=1)

        # Verify the employee has sufficient remaining days for each year involved
        for year, needed in days_by_year.items():
            if needed > self.remaining(employee, year):
                raise ValueError(
                    f"Insufficient leave days remaining for {year}: "
                    f"needed {needed}, remaining {self.remaining(employee, year)}."
                )

        # Deduct leave days
        for year, needed in days_by_year.items():
            self._used[employee][year] += needed

        self._employees.add(employee)
        self._requests[employee].append((start, end))

        return sum(days_by_year.values())

    def remaining(self, employee: str, year: int) -> int:
        return self.days_per_year - self._used[employee][year]

    def employees(self) -> list[str]:
        return sorted(self._employees)

    def requests_of(self, employee: str) -> list[tuple[date, date]]:
        return list(self._requests[employee])
